def _cache_key(request: dict) -> str:
    normalized = {k: Cache._normalize(v) for k, v in request.items()}
    return sha256(ujson.dumps(normalized, sort_keys=True).encode()).hexdigest()

def get(self, request: dict) -> dict | None:
    key = self._cache_key(request)
    row = self._get_conn().execute(
        "SELECT response FROM cache WHERE key = ?", (key,)
    ).fetchone()
    if row is None:
        with Cache._stats_lock:
            Cache._n_misses += 1
        logger.warning(
            "CACHE MISS (%s) key=%s model=%s — request not in cache",
            os.path.basename(self._db_path),
            key,
            request.get("model", "?"),
        )
        return None
    with Cache._stats_lock:
        Cache._n_hits += 1
    return ujson.loads(row[0])

